SELECT node_name_ja, path_name, company_count, company_count_rollup
FROM m_tax_node
WHERE node_level = {{level}}
ORDER BY company_count_rollup DESC, node_id
LIMIT {{top_n}}

SELECT company_id AS sec_code4, name, industry, relevance_score, revenue_share_est, fiscal_year, net_sales, ROUND(operating_margin * 100, 1) AS operating_margin_pct, ROUND(rnd_ratio * 100, 2) AS rnd_ratio_pct
FROM m_company_tax
WHERE entity_type = 'company' AND node_id = {{node_id}}
ORDER BY relevance_score DESC, net_sales DESC, company_id
LIMIT {{top_n}}

SELECT company_id AS sec_code4, name, industry, COUNT(*) AS node_count, MAX(relevance_score) AS max_relevance, MAX(fiscal_year) AS fiscal_year, MAX(net_sales) AS net_sales, ROUND(MAX(operating_margin) * 100, 1) AS operating_margin_pct, ROUND(MAX(rnd_ratio) * 100, 2) AS rnd_ratio_pct
FROM m_company_tax
WHERE entity_type = 'company' AND domain_id = {{domain_id}}
GROUP BY company_id, name, industry
ORDER BY max_relevance DESC, net_sales DESC, company_id
LIMIT {{top_n}}
